INSERT INTO reclaim_snapshots (id,company_id,run_id,as_of,policy_id,policy_revision,expected_count,context) VALUES ('39fa47c8-47d8-5e9a-9d9a-88b1293050b3','26c56ede-d5bd-5fad-8591-d729af9eaee9','a9cd0794-201a-58ad-8218-b12997e19d44','2026-10-21T09:00:00+09:00','0673ccd9-4e9b-5e92-bb81-28b949ef5224','1','1','{"policy":{"policy_id":"0673ccd9-4e9b-5e92-bb81-28b949ef5224","revision":1,"company_id":"26c56ede-d5bd-5fad-8591-d729af9eaee9","doc_id":"P2-A-POLICY","article":"POL-06 제1~5조 / FLOW 제7조","source_path":"data/phase2/company-a-policy.md","source_hash":"40e8eb84bc7ea099d18cba9dadb92f1565102638eb862bf70b0c2a376a2824d5","content":"# A사 Phase 2 임시 규정 · baseline-v1\n\n교육용 합성 데이터이며 실제 회사 규정·SaaS 공식 역할·가격이 아니다.\n\n## POL-06 제1조 — 신청 대상\n개발/분석 업무 권한은 해당 업무 담당자, Salesforce는 담당 고객 배정 직원, Datadog은 서비스 운영 담당자, Figma는 TF 디자인 담당자에게 제안한다. 실제 직군·배정은 서버 사실로 확인한다.\n## POL-06 제2조 — 비용\n서버의 구조화된 가격표와 잔여 예산을 사용한다. 사용량 기반 금액은 예상 예산 배정이며 실제 청구액이 아니다.\n## POL-06 제3조 — 예산 부족\n예산 부족이면 ON_HOLD로 보류한다. 재개 때 최신 정책·예산·승인 계획을 다시 검토한다.\n## POL-06 제4조 — 중복\n이미 필요한 권한이 있으면 변경 없이 안내한다. 기존 유료 좌석을 추가 구매하려는 요청은 거절한다.\n## POL-06 제5조 — 회수 후보\n프로젝트 지급 좌석은 TF 종료 후 연속 미사용 30일 이상이고 다른 활성 TF 이용 및 유효 유지 승인이 없으면 검토 후보로 제안한다. 종료 후 미사용 시작은 TF 종료 시각·마지막 사용 시각·할당 시각 중 가장 늦은 시각이다. 미조회는 미사용이 아니다. 퇴사자 유료 좌석도 별도 검토 후보로 제안한다. 비용 미확인은 UNKNOWN으로 남기며 실제 회수·예산 환입은 하지 않는다.\n## FLOW 제7조 — 승인 경로\n부서장 → IT 권한 담당자의 순서로 승인한다.\n본인 승인과 임의 승인자 추측은 금지한다. 담당자 식별은 회사·부서·플랫폼별 서버 매핑을 따른다.\n","is_mock":true},"rules":[{"rule_id":"d8e5e4fe-7759-546e-8f21-074b12ad464e","revision":1,"company_id":"26c56ede-d5bd-5fad-8591-d729af9eaee9","policy_id":"0673ccd9-4e9b-5e92-bb81-28b949ef5224","policy_revision":1,"code":"TF_ENDED_UNUSED_30D","idle_days":30,"exclude_other_active_tf":true,"exclude_retention":true},{"rule_id":"6a4c9687-2493-5d92-bde3-6385e995c695","revision":1,"company_id":"26c56ede-d5bd-5fad-8591-d729af9eaee9","policy_id":"0673ccd9-4e9b-5e92-bb81-28b949ef5224","policy_revision":1,"code":"EMPLOYEE_LEFT","idle_days":null,"exclude_other_active_tf":false,"exclude_retention":false}],"policy_hash":"40e8eb84bc7ea099d18cba9dadb92f1565102638eb862bf70b0c2a376a2824d5"}') ON CONFLICT DO NOTHING;
